{"content": "from fastapi import FastAPI
from pydantic import BaseModel, Field
from fastapi.testclient import TestClient
import json

app = FastAPI()

class ComplexType(BaseModel):
    name: str

class ItemWithRefV2(BaseModel):
    ref_field: ComplexType = Field(ComplexType(name="value"), alias="$ref")

@app.post("/items")
async def create_item(item: ItemWithRefV2):
    return item

def test_openapi_schema():
    schema = app.openapi()
    print(json.dumps(schema, indent=2))

if __name__ == "__main__":
    test_openapi_schema()
", "filepath": "repro_complex.py"}

